#!/bin/sh
# Build stock.txt from the day's movements log, one "SKU-# net" line per
# catalog SKU. Receipts add, shipments subtract. Catalog SKUs with no
# movements that day still get a line with net 0 (HANDOFF.md).
awk '{ if ($2 == "receipt") net[$1] += $3; else net[$1] -= $3 }
     END {
       n = split("SKU-1 SKU-2 SKU-3 SKU-4 SKU-9", catalog, " ")
       for (i = 1; i <= n; i++) { s = catalog[i]; if (s in net || !seen[s]++) print s, (s in net ? net[s] : 0) }
     }' movements.log | sort > stock.txt
